repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('city', 28), ('rovers', 38), ('rovers', 13), ('united', 42), ('united', 16), ('city', 36)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

