"""Labels for fixtures."""


def label_fixtures(names, fixtures):
    """Return (lookup, lines): a name -> goals dict and one 'name: goals' line per fixture."""
    pairs = zip(names, (x.goals for x in fixtures))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)


def largest_goals(fixtures):
    """Return the largest goals, or None when there are no fixtures."""
    values = [x.goals for x in fixtures]
    return max(values) if values else None


def describe_fixture(fixture):
    """Return a one-line description of a fixture."""
    return "%s: %s" % (fixture.club, fixture.goals)
